cssCode:
.spotlight {
  position: absolute; top: -50px;
  width: 150px; height: 400px;
  background: linear-gradient(to bottom, rgba(255,255,255,0.4) 0%, transparent 80%);
  clip-path: polygon(50% 0%, 100% 100%, 0% 100%);
  animation: sweepSpotlight 4s infinite alternate ease-in-out;
  transform-origin: top center; opacity: 0.6; mix-blend-mode: overlay;
}
.spot-1 { left: 20%; animation-delay: 0s; }
.spot-2 { right: 20%; background: linear-gradient(to bottom, rgba(0, 210, 255, 0.4) 0%, transparent 80%); animation-delay: -2s; }

@keyframes sweepSpotlight {
  0% { transform: rotate(-30deg); }
  100% { transform: rotate(30deg); }
}

